#!/bin/sh
# Seed Jethro's conf.php and persistent file storage on first start, then run
# Apache. /data is the app's persistent storage (umbreld-owned volume).
set -e

CONF=/data/conf.php

if [ ! -f "$CONF" ]; then
  cat > "$CONF" <<EOF
<?php
/**
 * Jethro conf.php — generated by the umbrelOS package on first start.
 * Edit freely; this file is never overwritten afterwards.
 * Full option reference: conf.php.sample in the Jethro installation.
 */

// Database (the bundled MariaDB service)
define('DB_HOST', '${JETHRO_DB_HOST}');
define('DB_TYPE', 'mysql');
define('DB_DATABASE', '${JETHRO_DB_NAME}');
define('DB_USERNAME', '${JETHRO_DB_USER}');
define('DB_PASSWORD', '${JETHRO_DB_PASSWORD}');
EOF
  echo "Seeded $CONF"
fi

chown www-data:www-data "$CONF" || true

# Uploaded documents/photos must survive app updates: symlink the in-app
# files dir into persistent storage.
mkdir -p /data/files
chown -R www-data:www-data /data/files || true
ln -sfn /data/files /var/www/html/files

exec "$@"
